import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Alerter & Telemetry","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/configuration/alerter.md","filePath":"openshield-xdp/configuration/alerter.md","lastUpdated":1785676970000}'),d={name:"openshield-xdp/configuration/alerter.md"};function r(n,e,o,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="alerter-telemetry" tabindex="-1">Alerter &amp; Telemetry <a class="header-anchor" href="#alerter-telemetry" aria-label="Permalink to &quot;Alerter &amp; Telemetry&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>OpenShield can dispatch real-time notifications to Discord via webhook when security events occur. The alerter runs in the collector goroutine, processing events from the BPF ring buffer and formatting them as Discord embeds.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">alerter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  webhook_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  events</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []                </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># empty = all events</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # events: [attack_start, attack_update, attack_end, ban_triggered, panic_mode]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  graph_enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # attach labeled traffic graph to attack-end alerts</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  show_banned_ips</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # inline banned IPs in ban alerts (default off: categorized .txt attached instead)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  geo_breakdown</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # continent/country share of banned IPs (needs GeoIP db)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  attack_updates</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # progress embeds while an attack is ongoing</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">telemetry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  poll_interval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  event_rate_limit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  top_offenders_count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  log_level</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">info</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  snapshot_interval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div><h3 id="alerter-fields" tabindex="-1">Alerter Fields <a class="header-anchor" href="#alerter-fields" aria-label="Permalink to &quot;Alerter Fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>alerter.enabled</code></td><td><code>bool</code></td><td><code>false</code></td><td>Master toggle for webhook alerts</td></tr><tr><td><code>alerter.webhook_url</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>Discord webhook URL (must be full <code>https://discord.com/api/webhooks/...</code>)</td></tr><tr><td><code>alerter.events</code></td><td><code>[]string</code></td><td><code>[]</code></td><td>Event filter — if not empty, only listed events trigger alerts</td></tr><tr><td><code>alerter.graph_enabled</code></td><td><code>bool</code></td><td><code>true</code></td><td>Attach the attack traffic graph (incoming vs passed PPS + BPS, labeled axes) to attack-end alerts</td></tr><tr><td><code>alerter.show_banned_ips</code></td><td><code>bool</code></td><td><code>false</code></td><td>List banned IPs inline in ban alerts; default off — a categorized <code>.txt</code> (grouped by reason) is attached instead</td></tr><tr><td><code>alerter.geo_breakdown</code></td><td><code>bool</code></td><td><code>true</code></td><td>Continent/country breakdown (% share + IP counts) in ban-batch alerts; requires the GeoIP database</td></tr><tr><td><code>alerter.attack_updates</code></td><td><code>bool</code></td><td><code>true</code></td><td>Send progress embeds while an attack is ongoing</td></tr></tbody></table><h2 id="rate-limiting" tabindex="-1">Rate Limiting <a class="header-anchor" href="#rate-limiting" aria-label="Permalink to &quot;Rate Limiting&quot;">​</a></h2><p>All webhook traffic flows through <strong>one paced dispatch queue</strong> (depth 64). A single dispatcher goroutine delivers messages with a minimum 1.2s spacing, so a burst of events during an attack can never trip Discord&#39;s webhook rate limit:</p><ul><li><strong>HTTP 429 honored</strong>: on a rate-limit response the dispatcher sleeps the server-provided <code>Retry-After</code> window and retries once before dropping.</li><li><strong>Overflow drops, never blocks</strong>: when the queue is full, new alerts are dropped and counted — the firewall never blocks on Discord.</li><li><strong>Coalesced warnings</strong>: alerter failures (429s, network errors) reach the log feed through a rate-limited sink (max one per 30s, with &quot;+N similar suppressed&quot;). They are never written to the terminal.</li><li><strong>Ban batching</strong>: individual ban events accumulate and flush as ONE merged &quot;IPs Banned&quot; embed every 5 seconds.</li></ul><h2 id="attack-progress-updates" tabindex="-1">Attack Progress Updates <a class="header-anchor" href="#attack-progress-updates" aria-label="Permalink to &quot;Attack Progress Updates&quot;">​</a></h2><p>While an attack is ongoing, progress embeds are dispatched at <strong>30s, 60s, 120s, 240s, 480s, 900s</strong> after the start, then every <strong>30 minutes</strong> (hard cap) for multi-hour attacks. Each update carries current/peak/avg rates, growth vs the attack&#39;s first seconds and vs the previous update, bans, new sources/s, drop rate, and the next update&#39;s ETA as a Discord-localized timestamp. Disable with <code>alerter.attack_updates: false</code>.</p><h2 id="attack-end-report-semantics" tabindex="-1">Attack-End Report Semantics <a class="header-anchor" href="#attack-end-report-semantics" aria-label="Permalink to &quot;Attack-End Report Semantics&quot;">​</a></h2><p>The attack-end embed reports two honest time figures:</p><ul><li><strong>Duration</strong> — how long attack traffic was actually elevated (start → traffic normalized, i.e. 2 sustained samples below the recovery threshold). <strong>State Cleared</strong> shows the full state-machine duration including the recovery window when it ran longer.</li><li><strong>Mitigation Time</strong> — &quot;blocked in Xs&quot;: when the <em>passed</em> rate (traffic getting through mitigation) collapsed. A flood whose sender keeps transmitting after being banned shows a high incoming line with a flat passed line — the graph&#39;s green <code>passed</code> line makes this visible.</li></ul><h2 id="event-types" tabindex="-1">Event Types <a class="header-anchor" href="#event-types" aria-label="Permalink to &quot;Event Types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Event Key</th><th>Trigger Condition</th><th>Discord Color</th></tr></thead><tbody><tr><td><code>attack_start</code></td><td>Baseline learner detects attack state (traffic &gt; threshold × spike%)</td><td>🔴 Red (<code>#FF0000</code>)</td></tr><tr><td><code>attack_update</code></td><td>Ongoing-attack progress (30s, growing intervals, 30min cap)</td><td>🟠 Amber (<code>#E67E22</code>)</td></tr><tr><td><code>attack_end</code></td><td>Attack state clears after recovery period</td><td>🟢 Green (<code>#00FF00</code>)</td></tr><tr><td><code>ban_triggered</code></td><td>IP banned (suspicion score reached threshold)</td><td>🟠 Orange (<code>#FF8C00</code>)</td></tr><tr><td><code>panic_mode</code></td><td>Panic circuit breaker activates (per-CPU PPS &gt; <code>panic_pps_rate</code>)</td><td>🟣 Magenta (<code>#FF00FF</code>)</td></tr><tr><td><code>new_source_flood</code></td><td>New unique IP rate exceeds <code>new_source_limit</code></td><td>🟡 Yellow (<code>#FFFF00</code>)</td></tr><tr><td><code>threshold_violation</code></td><td>IP exceeded threshold (PPS/BPS/TCP/UDP/ICMP/SYN)</td><td>⚪ Grey</td></tr><tr><td><code>subnet_ban</code></td><td>Auto subnet ban triggered (escalation)</td><td>🔵 Blue</td></tr><tr><td><code>entropy_spoof</code></td><td>Entropy-based spoofing detected</td><td>🟦 Cyan</td></tr><tr><td><code>ttl_anomaly</code></td><td>TTL deviation detected</td><td>🟦 Cyan</td></tr><tr><td><code>packet_size_anomaly</code></td><td>Avg packet size outside [min, max] range</td><td>🟦 Cyan</td></tr><tr><td><code>syn_fin_flood</code></td><td>SYN:FIN ratio exceeded threshold</td><td>🔴 Red</td></tr><tr><td><code>conn_rate_flood</code></td><td>Connection rate limit exceeded</td><td>🟡 Yellow</td></tr><tr><td><code>cluster_suspicious</code></td><td>Behavior cluster crossed the suspicious threshold</td><td>⚪ Grey</td></tr><tr><td><code>cluster_malicious</code></td><td>Behavior cluster crossed the malicious threshold</td><td>🔴 Red</td></tr></tbody></table><h2 id="event-rate-limiting-ring-buffer" tabindex="-1">Event Rate Limiting (Ring Buffer) <a class="header-anchor" href="#event-rate-limiting-ring-buffer" aria-label="Permalink to &quot;Event Rate Limiting (Ring Buffer)&quot;">​</a></h2><p>Separate from the webhook rate limiter, the BPF side also enforces an event emission cap:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>telemetry.event_rate_limit: 100   # max events/s emitted to ring buffer</span></span></code></pre></div><p>This is enforced in the XDP program itself — when the per-second event counter exceeds <code>event_rate_limit</code>, further event emissions to the ring buffer are silently suppressed. This protects both kernel memory and the userspace collector from being overwhelmed during an attack.</p><h2 id="telemetry-fields" tabindex="-1">Telemetry Fields <a class="header-anchor" href="#telemetry-fields" aria-label="Permalink to &quot;Telemetry Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>poll_interval</code></td><td><code>1</code></td><td>Seconds between collector reads of <code>global_stats_map</code></td></tr><tr><td><code>event_rate_limit</code></td><td><code>100</code></td><td>Max events/s emitted by BPF to ring buffer</td></tr><tr><td><code>top_offenders_count</code></td><td><code>20</code></td><td>Top N IPs displayed in TUI / logged</td></tr><tr><td><code>log_level</code></td><td><code>&quot;info&quot;</code></td><td><code>debug</code>, <code>info</code>, <code>warn</code>, or <code>error</code></td></tr><tr><td><code>snapshot_interval</code></td><td><code>1</code></td><td>Seconds between TUI stat snapshots</td></tr></tbody></table><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./reference">Configuration Reference</a> — All config fields</li><li><a href="./validation">Configuration Validation</a> — Runtime config updates</li><li><a href="/pingless-studios-docs/openshield-xdp/tui/overview">TUI Overview</a> — Live monitoring dashboard</li></ul>`,25)])])}const g=t(d,[["render",r]]);export{k as __pageData,g as default};
